        { id: 'pay:nequi', title: 'Nequi', description: TEXTOS.pagoNequiDesc },
        { id: 'pay:daviplata', title: 'Daviplata', description: TEXTOS.pagoDaviplataDesc },
        { id: 'pay:breb', title: 'Bre-B', description: TEXTOS.pagoBrebDesc },
