// Prompt de sistema para Gemini (clasificador de intenciones). También es
// "tono de marca": menciona el negocio, el rango de precios y los medios de pago.
const GEMINI_SISTEMA = 'Eres el clasificador de intenciones del bot de WhatsApp de VarMan Crew, una tienda colombiana de zapatos (tenis/sneakers). Analiza el mensaje del cliente y responde SOLO un JSON valido (sin markdown) con esta forma: {"intent":"<una de: saludo|ver_catalogo|buscar_marca|pregunta_precio|comprar|estado_pedido|aviso_stock|hablar_humano|otro>","respuesta":"<respuesta corta y calida en español colombiano, tono vendedor amable, max 2 frases, puede usar 1 emoji>","marca":"<solo si intent es buscar_marca: la marca normalizada en minusculas, corrigiendo ortografia (ej: addidas/las adidas -> adidas, naik -> nike); si no aplica, cadena vacia>","ref":"<solo si intent es aviso_stock y el cliente menciono una referencia: el numero de referencia con 2 digitos (ej: 05); si no, cadena vacia>","talla":"<solo si intent es aviso_stock y el cliente menciono una talla: el numero (ej: 40); si no, cadena vacia>"} Reglas: "saludo": saludos o inicios de conversacion, la respuesta da la bienvenida a VarMan Crew. "ver_catalogo": pide ver zapatos, modelos, catalogo o fotos en general. "buscar_marca": menciona o pregunta por una marca concreta de tenis (adidas, nike, jordan, new balance, puma, reebok, converse, vans, timberland, louis vuitton, etc.), aunque la escriba mal; ademas de la respuesta, devuelve la marca normalizada en el campo "marca". "pregunta_precio": pregunta precios en general o de una categoria. "comprar": ya quiere comprar o pedir algo concreto. "estado_pedido": pregunta como va, donde esta o cuando llega un pedido/compra que ya hizo. "aviso_stock": pide que le avisen cuando llegue, vuelva o haya de nuevo una talla o referencia agotada; extrae ref y talla si las menciona. "hablar_humano": pide hablar con una persona, asesor o el dueño. "otro": nada de lo anterior (quejas, envios, etc.), da una respuesta util y ofrece ver el catalogo o hablar con un asesor. Contexto: precios entre $235.000 y $480.000 COP, envios a todo Colombia, pagos por Nequi/Daviplata/Bre-B.';

// Prompt de sistema para el ASISTENTE conversacional (v6, flag BOT_ROBUSTEZ).
// A diferencia de GEMINI_SISTEMA (clasificador cuando NO hay pedido en curso),
// este corre cuando el bot YA está esperando un dato (talla, envío, pago…) y el
// cliente responde en lenguaje libre. Devuelve: si quiere un humano (handoff),
// el dato pedido si lo dio, y una respuesta cálida para preguntas extra o para
// guiar cuando el dato es incorrecto/fuera de lugar.
const GEMINI_ASISTENTE = 'Eres el asistente conversacional del bot de WhatsApp de VarMan Crew, una tienda colombiana de tenis/sneakers. El bot está en medio de un pedido y le pidió un dato al cliente, pero el cliente puede responder en lenguaje libre. Te doy el paso actual y el mensaje del cliente. Responde SOLO un JSON valido (sin markdown) con esta forma: {"handoff": true|false, "dato": "<el dato que pedia el paso si el cliente lo dio, si no cadena vacia>", "respuesta": "<mensaje corto y calido en español colombiano, tono vendedor amable, max 2 frases, max 1 emoji, o cadena vacia>"} Reglas: 1) handoff=true SOLO si el cliente pide claramente hablar con una persona/asesor/humano/dueño, o dice que el bot no le entiende y quiere atencion humana (ej: "quiero hablar con alguien", "me pasas un asesor", "una persona real", "no me estas entendiendo"); en ese caso deja "dato" y "respuesta" vacios. 2) Si el cliente DA el dato que pedia el paso (en el paso de talla, el numero 36-45; en datos de envio, nombre+direccion+ciudad+telefono), ponlo en "dato". Si ADEMAS de dar el dato pregunta o comenta algo extra (envios, precios, materiales, colores, tiempos), responde ESO breve en "respuesta"; si solo dio el dato sin nada mas, deja "respuesta" vacia. 3) Si el cliente NO da el dato pedido o responde algo fuera de lugar (ej: le piden la talla y dice "no se mi talla", "el rojo", o hace una pregunta), deja "dato" vacio y en "respuesta" ayudalo o aclara con calidez y reencaminalo al dato pedido (ej: si no sabe su talla, dale un tip para medirla y pidele el numero; nunca repitas seco la misma pregunta como robot). Contexto: tallas de la 36 a la 45, precios entre $235.000 y $480.000 COP, envios a todo Colombia (el costo exacto lo confirma un asesor), pagos por Nequi/Daviplata/Bre-B. No inventes datos que no sabes (costo o tiempo exacto de envio): ofrece que un asesor lo confirma.';

// Reemplaza {placeholders} por sus valores: T(TEXTOS.eligeReferencia, { ref: '05', precio: '$250.000' })
function T(plantilla, vars) {
  return String(plantilla).replace(/\{(\w+)\}/g, (m, k) => (vars && k in vars) ? String(vars[k]) : m);
}

// Arma el payload de WhatsApp de una notificación pendiente (backlog 11-12:
// guía de envío y reseña post-entrega, docs de tiendas/varman/
// notificacionesPendientes que escribe la app). Devuelve null si es una
// reseña y no existe LINK_RESENAS_FB (se omite con registro, nunca rompe).
// Vive AQUÍ porque lo usan DOS nodos (el Cerebro y el trigger horario).
function mensajeDeNotificacion(to, x) {
  if (x.tipo === 'guia') {
    return { messaging_product: 'whatsapp', to, type: 'text', text: {
      body: T(TEXTOS.guiaEnvio, { transportadora: x.transportadora || '?', guia: x.guia || '?' })
    } };
  }
  if (x.tipo === 'resena') {
    const link = String($env.LINK_RESENAS_FB || '').trim();
    if (!link) return null;
    const nombre = String(x.cliente_nombre || '').trim();
    return { messaging_product: 'whatsapp', to, type: 'text', text: {
      body: T(TEXTOS.resenaPedido, {
        nombre: nombre ? ', ' + nombre : '',
        producto: x.producto || ('tenis de la Ref ' + (x.ref || '?')),
        link
      })
    } };
  }
  return null;
}

// ============ TRIGGER HORARIO: carrito abandonado + reseñas/guías (v5) ============
// Corre cada hora con su propio Schedule Trigger mientras el workflow esté
// ACTIVO. La salida va DIRECTO al nodo "Enviar a WhatsApp": SOLO devuelve
// payloads válidos de mensaje (o [] si no hay nada que mandar).
//
// 1) CARRITO ABANDONADO (backlog 10): sesiones que eligieron referencia pero
//    no llegaron al comprobante, con 3-24h sin actividad → UN recordatorio
//    (se marca `recordatorio: true` en la sesión con updateMask, sin tocar el
//    resto). Quien escribió *cancelar* no tiene sesión → nunca le llega.
//    La ventana de 24h de WhatsApp está abierta por definición: updatedAt es
//    la hora del último mensaje del cliente.
// 2) NOTIFICACIONES PENDIENTES (backlog 11-12): docs que deja la app en
//    tiendas/varman/notificacionesPendientes (reseña al pasar a `entregado`,
//    guía de envío al guardarla). Solo se envían si la ventana de 24h está
//    abierta — se estima con botRate/{wa}.updatedAt (se actualiza con CADA
//    mensaje entrante del cliente; el barrido diario conserva esos docs 25h).
//    Sin ventana → quedan `pendiente` y el Cerebro las entrega apenas el
//    cliente vuelva a escribir. Reseña sin LINK_RESENAS_FB → `omitida_sin_link`.
// textos.js va pegado ANTES de este archivo (TEXTOS, T, mensajeDeNotificacion).
const H = this.helpers;
const crypto = require('crypto');
const FS_BASE = 'https://firestore.googleapis.com/v1/projects/varman-crew/databases/(default)/documents';

function b64url(buf) {
  return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
async function tokenAdmin() {
  const sa = JSON.parse(Buffer.from($env.FIREBASE_SA_B64, 'base64').toString('utf8'));
  const now = Math.floor(Date.now() / 1000);
  const header = b64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claims = b64url(JSON.stringify({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/datastore',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now, exp: now + 3600
  }));
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(header + '.' + claims);
  const jwt = header + '.' + claims + '.' + b64url(signer.sign(sa.private_key));
  const r = await H.httpRequest({
    method: 'POST', url: 'https://oauth2.googleapis.com/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + jwt,
    timeout: 15000, json: true
  });
  return r.access_token;
}
function unwrap(v) {
  if (v == null) return null;
  if ('integerValue' in v) return parseInt(v.integerValue, 10);
  if ('doubleValue' in v) return v.doubleValue;
  if ('booleanValue' in v) return v.booleanValue;
  if ('stringValue' in v) return v.stringValue;
  return null;
}
function fromFs(doc) {
  if (!doc || !doc.fields) return null;
  const o = {};
  for (const k in doc.fields) o[k] = unwrap(doc.fields[k]);
  return o;
}
function fmtPrecio(n) {
  return '$' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}
async function fsGetDoc(tok, path) {
  try {
    const d = await H.httpRequest({ method: 'GET', url: FS_BASE + '/' + path,
      headers: { Authorization: 'Bearer ' + tok }, json: true, timeout: 15000 });
    return fromFs(d);
  } catch (e) { return null; }
}
async function fsMerge(tok, path, obj) {
  const mask = Object.keys(obj).filter((k) => obj[k] !== undefined && obj[k] !== null)
    .map((k) => 'updateMask.fieldPaths=' + encodeURIComponent(k)).join('&');
  const fields = {};
  for (const k in obj) {
    const v = obj[k];
    if (v === undefined || v === null) continue;
    if (typeof v === 'number') fields[k] = { integerValue: String(Math.round(v)) };
    else if (typeof v === 'boolean') fields[k] = { booleanValue: v };
    else fields[k] = { stringValue: String(v) };
  }
  await H.httpRequest({ method: 'PATCH', url: FS_BASE + '/' + path + '?' + mask,
    headers: { Authorization: 'Bearer ' + tok, 'Content-Type': 'application/json' },
    body: { fields }, json: true, timeout: 15000 });
}
async function listar(tok, coleccion) {
  const docs = [];
  let pageToken = '';
  do {
    const url = FS_BASE + '/tiendas/varman/' + coleccion + '?pageSize=300' + (pageToken ? '&pageToken=' + encodeURIComponent(pageToken) : '');
    const r = await H.httpRequest({ method: 'GET', url,
      headers: { Authorization: 'Bearer ' + tok }, json: true, timeout: 20000 });
    for (const d of (r.documents || [])) {
      const o = fromFs(d) || {};
      o._id = d.name.split('/').pop();
      docs.push(o);
    }
    pageToken = r.nextPageToken || '';
  } while (pageToken);
  return docs;
}
function msjTexto(to, body) {
  return { messaging_product: 'whatsapp', to, type: 'text', text: { body } };
}

const HORA_MS = 3600 * 1000;
const salida = [];
const tok = await tokenAdmin();
const dueno = String($env.OWNER_WHATSAPP || '').replace(/\D/g, '');

// ---- 1. carrito abandonado ----
try {
  const sesiones = await listar(tok, 'botSesiones');
  for (const s of sesiones) {
    if (!s.estado || !s.ref) continue;              // sin pedido en curso (o solo fuente)
    if (s.recordatorio === true) continue;          // máx 1 recordatorio por sesión
    if (!s._id || s._id === dueno) continue;        // al dueño no (sesiones de prueba)
    const edad = Date.now() - Date.parse(s.updatedAt || '');
    if (isNaN(edad) || edad < 3 * HORA_MS || edad > 24 * HORA_MS) continue;
    const nombre = String(s.nombrePerfil || '').trim();
    const plantilla = s.talla ? TEXTOS.carritoAbandonado : TEXTOS.carritoAbandonadoSinTalla;
    // se marca ANTES de encolar: mejor perder un recordatorio que repetirlo
    await fsMerge(tok, 'tiendas/varman/botSesiones/' + s._id, { recordatorio: true });
    salida.push(msjTexto(s._id, T(plantilla, {
      nombre: nombre ? ' ' + nombre : '',
      ref: s.ref, talla: s.talla || '', total: fmtPrecio(s.precio || 0)
    })));
  }
} catch (e) {}

// ---- 2. notificaciones pendientes (reseña / guía) con ventana de 24h ----
try {
  const pendientes = (await listar(tok, 'notificacionesPendientes'))
    .filter((x) => x.estado === 'pendiente');
  for (const x of pendientes) {
    const wa = String(x.cliente_wa || '').replace(/\D/g, '');
    if (!wa) continue;
    // ventana de servicio: último mensaje entrante del cliente hace <24h
    const rate = await fsGetDoc(tok, 'tiendas/varman/botRate/' + wa);
    const ultimo = rate && rate.updatedAt ? Date.now() - Date.parse(rate.updatedAt) : Infinity;
    if (!(ultimo < 24 * HORA_MS)) continue;         // sin ventana: la entrega el Cerebro
    const m = mensajeDeNotificacion(wa, x);
    const estadoNuevo = m ? 'enviada' : (x.tipo === 'resena' ? 'omitida_sin_link' : 'omitida');
    await fsMerge(tok, 'tiendas/varman/notificacionesPendientes/' + x._id,
      { estado: estadoNuevo, actualizado: new Date().toISOString() });
    if (m) salida.push(m);
  }
} catch (e) {}

return salida.map((m) => ({ json: m }));

